        #zipfannotation(datasets, abbreviations["formula"], thresholds["formula"], target = "formula", keyword = keyword, inputstep = inputstep, rankinglimit = rankinglimit_formula, combination = combination_formula, reset = False, mode="fdr")
        #zipfannotation(datasets, abbreviations["class"], thresholds["class"], target = "class", keyword = keyword, inputstep = inputstep, rankinglimit = rankinglimit_class, combination = combination_class, reset = False, mode="fdr")
